/** Auto-extracted form markup from master-client-intake.html — do not edit by hand unless syncing SoT. */
export const ANKETAPLAN_FORM_HTML = "\n  <header class=\"hero wrap\">\n    <div class=\"eyebrow\">Основа нашей персональной работы</div>\n    <h1>Анкета для полноценного <i>месячного плана</i></h1>\n    <p class=\"lead\">Эта анкета необходима, чтобы я мог полноценно оценить твоё текущее состояние: здоровье, особенности тела, движение, нагрузки, сон, питание, восстановление и образ жизни. Без этой информации невозможно составить действительно точную, безопасную и полезную программу именно для тебя.</p>\n    <p class=\"principle\">Я не работаю по шаблону и не хочу давать общие рекомендации. Мне важно понимать человека целиком — его историю, привычки, возможности и ограничения. <strong>Я люблю точность, мелочи и детали, потому что именно из них складывается большой результат.</strong> Поэтому твои подробные и честные ответы — это уже важная часть нашей работы и основа плана, за который ты заплатил.</p>\n    <div class=\"intro-grid\">\n      <div class=\"intro-card\"><b>25–40 минут</b><span>Можно пройти в несколько подходов</span></div>\n      <div class=\"intro-card\"><b>Автосохранение</b><span>Ответы остаются на этом устройстве</span></div>\n      <div class=\"intro-card\"><b>Без правильных ответов</b><span>Честность важнее идеальной картины</span></div>\n    </div>\n  </header>\n\n  <div class=\"sticky\"><div class=\"progress-shell\"><div class=\"progress-top\"><span id=\"chapterTitle\">Глава 1 · Ты и твоя цель</span><span class=\"saved\" id=\"saveState\">Ответы сохраняются</span></div><div class=\"progress-track\"><div class=\"progress-bar\" id=\"progressBar\"></div></div></div></div>\n\n  <main class=\"wrap\"><form id=\"masterForm\" novalidate>\n    <section class=\"chapter active\" data-title=\"Ты и твоя цель\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 1 из 12</div><h2>Начнём с тебя</h2><p class=\"chapter-desc\">Сначала — не диагнозы и цифры. Расскажи, зачем тебе другое тело и что действительно должно измениться.</p></div>\n      <div class=\"section\"><h3>Карточка клиента</h3><p class=\"section-note\">Основные данные для связи и расчёта нагрузки.</p>\n        <div class=\"grid2\"><div class=\"field\"><label class=\"label\" for=\"name\">Имя и фамилия <span class=\"req\">*</span></label><input class=\"control\" id=\"name\" name=\"Имя и фамилия\" required autocomplete=\"name\"></div><div class=\"field\"><label class=\"label\" for=\"birth\">Дата рождения</label><input class=\"control\" id=\"birth\" name=\"Дата рождения\" type=\"date\"></div></div>\n        <div class=\"grid3\"><div class=\"field\"><label class=\"label\">Пол</label><select class=\"control\" name=\"Пол\" id=\"sex\"><option value=\"\">Не выбрано</option><option>Мужской</option><option>Женский</option><option>Предпочитаю не указывать</option></select></div><div class=\"field\"><label class=\"label\">Рост, см</label><input class=\"control\" id=\"height\" name=\"Рост, см\" type=\"number\" min=\"80\" max=\"240\"></div><div class=\"field\"><label class=\"label\">Вес утром, кг</label><input class=\"control\" id=\"weight\" name=\"Вес, кг\" type=\"number\" min=\"20\" max=\"350\" step=\"0.1\" placeholder=\"По возможности натощак\"></div></div>\n        <div class=\"grid3\"><div class=\"field\"><label class=\"label\">Талия на уровне пупка, см</label><input class=\"control\" name=\"Талия, см\" type=\"number\" min=\"30\" max=\"250\" step=\".1\"></div><div class=\"field\"><label class=\"label\">Обхват бёдер, см</label><input class=\"control\" name=\"Бёдра, см\" type=\"number\" min=\"40\" max=\"250\" step=\".1\"></div><div class=\"field\"><label class=\"label\">Обхват груди, см</label><input class=\"control\" name=\"Грудь, см\" type=\"number\" min=\"40\" max=\"250\" step=\".1\"></div></div>\n        <div class=\"field\"><label class=\"label\">Насколько активен твой обычный день?</label><span class=\"hint\">Нужно для примерного расчёта суточной потребности в энергии.</span><select class=\"control\" id=\"activityFactor\" name=\"Уровень повседневной активности\"><option value=\"\">Выбери наиболее похожий вариант</option><option value=\"1.2\">В основном сижу, почти нет тренировок</option><option value=\"1.375\">Много хожу или тренируюсь 1–3 раза в неделю</option><option value=\"1.55\">Тренируюсь 3–5 раз в неделю</option><option value=\"1.725\">Физическая работа или тренировки 6–7 раз в неделю</option><option value=\"1.9\">Очень высокая ежедневная нагрузка / две тренировки в день</option></select></div>\n        <div class=\"calc-box\" id=\"bodyCalc\"><div class=\"calc-grid\"><div class=\"metric\"><b id=\"ageResult\">—</b><span>возраст</span></div><div class=\"metric\"><b id=\"bmiResult\">—</b><span>индекс массы тела</span></div><div class=\"metric\"><b id=\"bmrResult\">—</b><span>основной обмен, ккал</span></div><div class=\"metric\"><b id=\"tdeeResult\">—</b><span>поддержание веса, ккал/день</span></div></div><p class=\"skip\" id=\"calcNote\">Расчёт появится после заполнения даты рождения, пола, роста, веса и активности.</p><input type=\"hidden\" name=\"Расчёт: возраст\" id=\"ageValue\"><input type=\"hidden\" name=\"Расчёт: ИМТ\" id=\"bmiValue\"><input type=\"hidden\" name=\"Расчёт: основной обмен\" id=\"bmrValue\"><input type=\"hidden\" name=\"Расчёт: поддержание калорий\" id=\"tdeeValue\"></div>\n        <div class=\"grid2\"><div class=\"field\"><label class=\"label\">Город / часовой пояс</label><input class=\"control\" name=\"Город и часовой пояс\" placeholder=\"Москва · UTC+3\"></div><div class=\"field\"><label class=\"label\">Telegram / телефон</label><input class=\"control\" name=\"Контакт\" autocomplete=\"tel\"></div></div>\n        <div class=\"field\"><label class=\"label\">Профессия и формат рабочего дня</label><textarea class=\"control\" name=\"Работа\" placeholder=\"Чем занимаешься, сколько сидишь, как проходит обычный день\"></textarea></div>\n        <div class=\"field\"><span class=\"label\">Для кого план?</span><div class=\"chips\"><label class=\"chip\"><input type=\"radio\" name=\"Для кого план\" value=\"Для себя\" checked data-branch=\"child:no\"><span>Для себя</span></label><label class=\"chip\"><input type=\"radio\" name=\"Для кого план\" value=\"Для ребёнка\" data-branch=\"child:yes\"><span>Для ребёнка</span></label></div></div>\n        <div class=\"conditional\" data-show=\"child:yes\"><div class=\"grid2\"><div class=\"field\"><label class=\"label\">Имя и возраст ребёнка</label><input class=\"control\" name=\"Ребёнок: имя и возраст\"></div><div class=\"field\"><label class=\"label\">Кто заполняет и кем приходится</label><input class=\"control\" name=\"Ребёнок: представитель\"></div></div><div class=\"field\"><label class=\"label\">Развитие, диагнозы, секции и особенности нагрузки</label><textarea class=\"control\" name=\"Ребёнок: особенности\"></textarea></div><div class=\"notice\"><strong>Для несовершеннолетнего</strong> программа и обмен материалами возможны только с согласия законного представителя.</div></div>\n      </div>\n      <div class=\"section\"><h3>Главный запрос</h3><p class=\"section-note\">Выбери всё актуальное, затем сформулируй один главный приоритет.</p><div class=\"field\"><div class=\"chips\" data-group=\"Запросы\"><label class=\"chip\"><input type=\"checkbox\" value=\"Боль\"><span>Боль</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Скованность\"><span>Скованность</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Осанка\"><span>Осанка</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сила\"><span>Сила</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Мышечная масса\"><span>Мышечная масса</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Снижение жира\"><span>Снижение жира</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Выносливость\"><span>Выносливость</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Мобильность\"><span>Мобильность</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Спортивный результат\"><span>Спорт</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Энергия\"><span>Энергия</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сон\"><span>Сон</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Стресс\"><span>Стресс</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Долголетие\"><span>Долголетие</span></label></div></div>\n        <div class=\"field\"><label class=\"label\">Почему ты решил заняться телом именно сейчас? <span class=\"req\">*</span></label><textarea class=\"control\" name=\"Почему сейчас\" required></textarea></div><div class=\"field\"><label class=\"label\">Если за 30 дней можно изменить только одну вещь — какую?</label><textarea class=\"control\" name=\"Один приоритет на 30 дней\"></textarea></div>\n        <div class=\"grid3\"><div class=\"field\"><label class=\"label\">Результат через 30 дней</label><textarea class=\"control\" name=\"Цель 30 дней\"></textarea></div><div class=\"field\"><label class=\"label\">Через 3 месяца</label><textarea class=\"control\" name=\"Цель 3 месяца\"></textarea></div><div class=\"field\"><label class=\"label\">Через год</label><textarea class=\"control\" name=\"Цель год\"></textarea></div></div><div class=\"field\"><label class=\"label\">Что этот результат изменит в твоей жизни?</label><textarea class=\"control\" name=\"Смысл результата\"></textarea></div>\n      </div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Здоровье и самочувствие\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 2 из 12</div><h2>Здоровье и самочувствие</h2><p class=\"chapter-desc\">Расскажи всё, что может повлиять на выбор упражнений, интенсивность и восстановление. Если чего-то не знаешь — просто напиши «не знаю».</p></div>\n      <div class=\"section\"><h3>Самочувствие во время нагрузки</h3><p class=\"section-note\">Выбери только то, что у тебя действительно бывало во время тренировки, быстрой ходьбы, подъёма по лестнице или другой нагрузки. Это помогает понять, как ты переносишь физическую активность.</p><div class=\"chips\" data-group=\"Самочувствие при нагрузке\"><label class=\"chip\"><input type=\"checkbox\" value=\"Боль/давление в груди\"><span>Боль или давление в груди</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Обморок/предобморок\"><span>Обморок или предобморочное состояние</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Необычная одышка\"><span>Сильная необычная одышка</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Перебои сердцебиения\"><span>Перебои сердцебиения</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Внезапная слабость/онемение\"><span>Внезапная слабость или онемение</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет\"><span>Ничего из перечисленного</span></label></div></div>\n      <div class=\"section\"><h3>Диагностированные заболевания</h3><p class=\"section-note\">Есть ли у тебя заболевания или состояния, которые когда-либо были диагностированы врачом? Выбери систему организма, к которой относится диагноз. После выбора ниже напиши точное название, когда его поставили и какие рекомендации тебе давали.</p><div class=\"chips\" data-group=\"Диагностированные состояния\"><label class=\"chip\"><input type=\"checkbox\" value=\"Сердце/сосуды\"><span>Сердце и сосуды</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Давление\"><span>Артериальное давление</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Дыхательная система\"><span>Лёгкие и дыхательная система</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Диабет/эндокринология\"><span>Гормональная система / диабет</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Почки\"><span>Почки и мочевыделительная система</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Неврология\"><span>Нервная система</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Опорно-двигательная система\"><span>Суставы, позвоночник, мышцы</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"ЖКТ\"><span>Желудок и кишечник</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Аутоиммунное\"><span>Аутоиммунные состояния</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Другое\"><span>Другое</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет диагностированных заболеваний\"><span>Диагнозов нет</span></label></div><div class=\"field\"><label class=\"label\">Напиши диагнозы и важные подробности</label><textarea class=\"control\" name=\"Диагнозы и ограничения\" placeholder=\"Например: гипертония, поставили в 2022 году; принимаю назначенный препарат; рекомендовали контролировать давление и избегать резкого повышения нагрузки\"></textarea></div><div class=\"field\"><label class=\"label\">Какие обследования и анализы проходил за последний год?</label><span class=\"hint\">Если результаты есть под рукой, перечисли название, дату и основные показатели. Если нет — оставь поле пустым.</span><textarea class=\"control\" name=\"Обследования и анализы\" placeholder=\"Например: общий анализ крови, глюкоза, липиды, ферритин, витамин D, ЭКГ и другие обследования\"></textarea></div><div class=\"field\"><label class=\"label\">Есть ли заболевания сердца, диабет или другие серьёзные заболевания у близких родственников?</label><textarea class=\"control\" name=\"Семейная история здоровья\" placeholder=\"Укажи родственника, заболевание и примерный возраст, когда оно проявилось\"></textarea></div></div>\n      <div class=\"section\"><h3>Давление и сердце</h3><div class=\"grid3\"><div class=\"field\"><label class=\"label\">Обычное давление</label><input class=\"control\" name=\"Обычное давление\" placeholder=\"Например, 120/80 или не знаю\"></div><div class=\"field\"><label class=\"label\">Максимум за 3 месяца</label><input class=\"control\" name=\"Максимальное давление\"></div><div class=\"field\"><label class=\"label\">Пульс в покое</label><input class=\"control\" name=\"Пульс в покое\" placeholder=\"уд/мин или не знаю\"></div></div><div class=\"field\"><label class=\"label\">Как часто измеряешь? Бывают ли скачки, головные боли, головокружение?</label><textarea class=\"control\" name=\"Контроль давления\"></textarea></div></div>\n      <div class=\"section\"><h3>Никотин и частота простуд</h3><div class=\"field\"><label class=\"label\">Используешь ли сейчас сигареты, вейп, кальян, снюс или другие формы никотина?</label><textarea class=\"control\" name=\"Никотин\" placeholder=\"Что именно, как часто и как давно; если бросил — когда и какой был стаж\"></textarea></div><div class=\"field\"><label class=\"label\">Как часто болел простудными или другими инфекциями за последний год?</label><textarea class=\"control\" name=\"Частота простуд\" placeholder=\"Сколько раз, сколько обычно длится болезнь и насколько долго после неё возвращается энергия\"></textarea></div></div>\n      <div class=\"section\"><h3>Лекарства и добавки</h3><div class=\"field\"><label class=\"label\">Какие лекарства принимаешь регулярно или курсами?</label><span class=\"hint\">Для каждого укажи название, дозировку, время приёма и для чего оно назначено.</span><textarea class=\"control\" name=\"Лекарства\" placeholder=\"Например: название — дозировка — утром/вечером — назначено для...\"></textarea></div><div class=\"field\"><label class=\"label\">Какие витамины, добавки и спортивное питание принимаешь?</label><span class=\"hint\">Укажи название, дозировку, как давно принимаешь и какой результат ожидаешь.</span><textarea class=\"control\" name=\"Добавки\"></textarea></div><div class=\"field\"><label class=\"label\">Есть ли аллергии или продукты, лекарства и добавки, на которые организм реагирует плохо?</label><textarea class=\"control\" name=\"Аллергии\" placeholder=\"Что именно и какая возникает реакция\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"История тела и боль\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 3 из 12</div><h2>История тела</h2><p class=\"chapter-desc\">Не только что болит, но и как тело пришло в эту точку.</p></div>\n      <div class=\"section\"><h3>Травмы, операции, реабилитация</h3><div class=\"field\"><label class=\"label\">Травмы и переломы за всю жизнь</label><textarea class=\"control\" name=\"Травмы\" placeholder=\"Год, зона, обстоятельства, что осталось сейчас\"></textarea></div><div class=\"field\"><label class=\"label\">Операции, госпитализации, реабилитации</label><textarea class=\"control\" name=\"Операции и реабилитация\"></textarea></div><div class=\"field\"><label class=\"label\">Что уже пробовал и что реально помогало / ухудшало?</label><textarea class=\"control\" name=\"Предыдущая помощь\"></textarea></div></div>\n      <div class=\"section\"><h3>Карта боли</h3><p class=\"section-note\">Сначала выбери все зоны, которые беспокоят. Для каждой выбранной зоны появится отдельная карточка — так боль в шее не смешается, например, с болью в пояснице или колене.</p><div class=\"chips\" data-group=\"Зоны боли\" id=\"painZones\"><label class=\"chip\"><input type=\"checkbox\" value=\"Голова/челюсть\"><span>Голова / челюсть</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Шея\"><span>Шея</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Плечо/рука\"><span>Плечо / рука</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Грудной отдел\"><span>Грудной отдел</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Поясница\"><span>Поясница</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Таз/бедро\"><span>Таз / бедро</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Колено\"><span>Колено</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Голеностоп/стопа\"><span>Голеностоп / стопа</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Боли нет\"><span>Сейчас ничего не болит</span></label></div><div id=\"painDetails\"></div><div class=\"field\"><label class=\"label\">Как все эти ощущения в целом влияют на твою жизнь?</label><textarea class=\"control\" name=\"Влияние боли\" placeholder=\"Например: мешают спать, долго сидеть, работать, гулять, тренироваться или играть с детьми\"></textarea></div></div>\n      <div class=\"section\"><h3>Движения в обычной жизни</h3><p class=\"section-note\">Выбери движения, которые вызывают боль или дискомфорт, ощущаются скованно, даются заметно тяжелее или которые ты стараешься избегать. Если движение выполняется свободно — выбирать его не нужно.</p><div class=\"chips\" data-group=\"Сложные движения\"><label class=\"chip\"><input type=\"checkbox\" value=\"Долго сидеть\"><span>Долго сидеть</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Стоять\"><span>Долго стоять</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Ходить\"><span>Ходить</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Лестница\"><span>Подниматься по лестнице</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Приседать\"><span>Приседать / вставать со стула</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Наклоняться\"><span>Наклоняться / надевать обувь</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Поднимать руки\"><span>Поднимать руки вверх</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Бегать/прыгать\"><span>Бегать / прыгать</span></label></div><div class=\"field\"><label class=\"label\">Что именно происходит при выбранных движениях?</label><textarea class=\"control\" name=\"Избегаемые движения\" placeholder=\"Например: после 20 минут сидения тянет поясницу; при подъёме по лестнице болит правое колено; боюсь наклоняться после старой травмы\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Движение и опыт тренировок\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 4 из 12</div><h2>Двигательная биография</h2><p class=\"chapter-desc\">Опыт важнее ярлыка «новичок»: что тело уже умеет, любит и плохо переносит.</p></div>\n      <div class=\"section\"><h3>От детства до сегодня</h3><div class=\"field\"><label class=\"label\">Спорт, танцы, секции и периоды регулярных тренировок</label><textarea class=\"control\" name=\"Двигательная биография\" placeholder=\"Возраст, направление, длительность, уровень, причины перерыва\"></textarea></div><div class=\"field\"><span class=\"label\">С чем есть опыт?</span><div class=\"chips\" data-group=\"Опыт направлений\"><label class=\"chip\"><input type=\"checkbox\" value=\"Тренажёрный зал\"><span>Тренажёрный зал</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Силовые\"><span>Силовые</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Функциональный тренинг\"><span>Функциональный</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Йога\"><span>Йога</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Пилатес\"><span>Пилатес</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Animal Flow\"><span>Animal Flow</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Калистеника\"><span>Калистеника</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Бег\"><span>Бег</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Плавание\"><span>Плавание</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Единоборства\"><span>Единоборства</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Командный спорт\"><span>Командный спорт</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Танцы\"><span>Танцы</span></label></div></div><div class=\"field\"><label class=\"label\">Что нравилось, что не нравилось и почему?</label><textarea class=\"control\" name=\"Отношение к направлениям\"></textarea></div><div class=\"field\"><label class=\"label\">Техника и рабочие веса, если знаешь</label><textarea class=\"control\" name=\"Силовой опыт\" placeholder=\"Присед, тяга, жим, подтягивания; уверенность в технике; работа с тренером\"></textarea></div></div>\n      <div class=\"section\"><h3>Текущая активность</h3><div class=\"grid3\"><div class=\"field\"><label class=\"label\">Шагов в день</label><input class=\"control\" name=\"Шаги в день\"></div><div class=\"field\"><label class=\"label\">Тренировок в неделю</label><input class=\"control\" name=\"Тренировок в неделю\" type=\"number\" min=\"0\" max=\"14\"></div><div class=\"field\"><label class=\"label\">Сидения в день, часов</label><input class=\"control\" name=\"Сидение часов\" type=\"number\" min=\"0\" max=\"24\" step=\".5\"></div></div><div class=\"field\"><label class=\"label\">Опиши последнюю обычную неделю активности</label><textarea class=\"control\" name=\"Текущая активность\"></textarea></div><div class=\"field\"><label class=\"label\">Как тело отвечает во время нагрузки и на следующий день?</label><textarea class=\"control\" name=\"Ответ на нагрузку\"></textarea></div></div>\n      <div class=\"section\"><h3>Качества движения</h3><div class=\"grid2\"><div class=\"field\"><span class=\"label\">Мобильность</span><div class=\"scale\" data-scale=\"Самооценка мобильности 0-10\"></div></div><div class=\"field\"><span class=\"label\">Координация</span><div class=\"scale\" data-scale=\"Самооценка координации 0-10\"></div></div><div class=\"field\"><span class=\"label\">Баланс</span><div class=\"scale\" data-scale=\"Самооценка баланса 0-10\"></div></div><div class=\"field\"><span class=\"label\">Чувство тела</span><div class=\"scale\" data-scale=\"Чувство тела 0-10\"></div></div></div><div class=\"field\"><label class=\"label\">Где чувствуешь скованность, асимметрию или слабый контроль?</label><textarea class=\"control\" name=\"Ограничения движения\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Дыхание, сон и ритмы\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 5 из 12</div><h2>Дыхание и сон</h2><p class=\"chapter-desc\">То, как ты восстанавливаешься ночью и регулируешь напряжение днём.</p></div>\n      <div class=\"section\"><h3>Дыхание</h3><div class=\"chips\" data-group=\"Особенности дыхания\"><label class=\"chip\"><input type=\"checkbox\" value=\"Дышу ртом\"><span>Дыхание ртом</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Заложен нос\"><span>Заложенность носа</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Частые вздохи\"><span>Частые вздохи</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нехватка воздуха\"><span>Нехватка воздуха</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Трудно расслабиться\"><span>Трудно расслабиться</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет особенностей\"><span>Ничего из этого</span></label></div><div class=\"field\"><label class=\"label\">Что замечаешь в дыхании в покое, при стрессе и нагрузке?</label><textarea class=\"control\" name=\"Дыхание подробно\"></textarea></div></div>\n      <div class=\"section\"><h3>Сон и ежедневный режим</h3><p class=\"section-note\">Эта информация помогает понять, сколько у тебя реального ресурса для тренировок и в какое время нагрузка будет переноситься лучше.</p><div class=\"grid3\"><div class=\"field\"><label class=\"label\">Во сколько обычно ложишься?</label><input class=\"control\" name=\"Время отбоя\" type=\"time\"></div><div class=\"field\"><label class=\"label\">Во сколько обычно встаёшь?</label><input class=\"control\" name=\"Время подъёма\" type=\"time\"></div><div class=\"field\"><label class=\"label\">Сколько часов спишь?</label><input class=\"control\" name=\"Продолжительность сна\" type=\"number\" min=\"0\" max=\"16\" step=\".5\"></div></div><div class=\"field\"><span class=\"label\">Что регулярно происходит со сном?</span><span class=\"hint\">Выбери всё, что бывает хотя бы несколько раз в неделю.</span><div class=\"chips\" data-group=\"Сон: особенности\"><label class=\"chip\"><input type=\"checkbox\" value=\"Долго засыпаю\"><span>Засыпаю дольше 30 минут</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Просыпаюсь ночью\"><span>Просыпаюсь ночью</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Храп\"><span>Храплю</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Паузы дыхания замечали\"><span>Замечали паузы дыхания</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сонливость днём\"><span>Хочется спать днём</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сменный график\"><span>Работаю по сменам</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Режим сбивается\"><span>Режим часто сбивается</span></label></div></div><div class=\"field\"><span class=\"label\">Насколько сон восстанавливает?</span><div class=\"scale\" data-scale=\"Восстановление сном 0-10\"></div><div class=\"scale-ends\"><span>просыпаюсь разбитым</span><span>просыпаюсь полностью восстановленным</span></div></div><div class=\"field\"><label class=\"label\">Опиши свой вечер и первые часы после пробуждения</label><span class=\"hint\">Напиши, пользуешься ли телефоном в кровати, во сколько пьёшь последний кофе или алкоголь, есть ли прогулка и дневной свет утром, проветриваешь ли спальню и что обычно делаешь перед сном.</span><textarea class=\"control\" name=\"Циркадные привычки\" placeholder=\"Например: утром сразу телефон, на улицу выхожу через час; последний кофе в 17:00; вечером работаю за ноутбуком; перед сном принимаю душ и читаю\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Питание и отношения с едой\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 6 из 12</div><h2>Честно про своё питание</h2><p class=\"chapter-desc\">Пожалуйста, опиши питание таким, какое оно есть сейчас. Мне не нужна идеальная картинка — честные ответы помогут точнее рассчитать нагрузку, восстановление и рекомендации для твоего месячного плана.</p></div>\n      <div class=\"section\"><h3>Как ты обычно питаешься</h3><div class=\"field\"><label class=\"label\">Что и когда ты обычно ешь в будний день?</label><span class=\"hint\">Перечисли все основные приёмы пищи, перекусы и напитки. Достаточно обычного примера, дневник питания сейчас вести не нужно.</span><textarea class=\"control\" name=\"Рацион буднего дня\" placeholder=\"Например: 08:00 — яйца и кофе; 13:00 — суп и второе; 17:00 — сладкое; 21:00 — ужин\"></textarea></div><div class=\"field\"><label class=\"label\">Чем питание в выходные отличается от будней?</label><textarea class=\"control\" name=\"Рацион выходного дня\" placeholder=\"Например: ем позже, чаще заказываю доставку, больше сладкого или алкоголя\"></textarea></div><div class=\"grid3\"><div class=\"field\"><label class=\"label\">Сколько воды пьёшь за день?</label><input class=\"control\" name=\"Вода\" placeholder=\"Примерно в литрах\"></div><div class=\"field\"><label class=\"label\">Кофе, чай и энергетики</label><input class=\"control\" name=\"Кофеин\" placeholder=\"Что, сколько чашек и до какого времени\"></div><div class=\"field\"><label class=\"label\">Алкоголь</label><input class=\"control\" name=\"Алкоголь\" placeholder=\"Что, как часто и примерно сколько\"></div></div><div class=\"field\"><span class=\"label\">Какую воду обычно пьёшь?</span><div class=\"chips\" data-group=\"Источник питьевой воды\"><label class=\"chip\"><input type=\"checkbox\" value=\"Бутилированная\"><span>Бутилированная</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"После фильтра\"><span>После фильтра</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Из-под крана\"><span>Из-под крана</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Минеральная\"><span>Минеральная</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"В основном чай/кофе\"><span>В основном чай / кофе</span></label></div></div><div class=\"field\"><label class=\"label\">Есть ли продукты, которые не ешь или после которых чувствуешь себя хуже?</label><textarea class=\"control\" name=\"Пищевые ограничения\" placeholder=\"Укажи продукт и реакцию: тяжесть, вздутие, изжога, изменение стула, зуд, высыпания или другое\"></textarea></div></div>\n      <div class=\"section\"><h3>Пищевые привычки</h3><p class=\"section-note\">Выбери то, что действительно повторяется. Это поможет сделать рекомендации выполнимыми в твоей реальной жизни.</p><div class=\"chips\" data-group=\"Пищевое поведение\"><label class=\"chip\"><input type=\"checkbox\" value=\"Ем на стрессе\"><span>Ем больше на фоне стресса</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Пропускаю приёмы\"><span>Часто пропускаю приёмы пищи</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Переедаю вечером\"><span>Основная еда приходится на вечер</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Жёстко ограничиваю\"><span>Чередую строгие ограничения и срывы</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Чувство вины\"><span>Испытываю чувство вины после еды</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Эпизоды потери контроля\"><span>Бывает сложно остановиться</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Часто ем вне дома\"><span>Часто ем вне дома / заказываю</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Не умею готовить\"><span>Не хватает навыка или времени готовить</span></label></div><div class=\"field\"><label class=\"label\">Какие диеты и способы изменить вес ты уже пробовал?</label><textarea class=\"control\" name=\"История диет\" placeholder=\"Что делал, сколько времени, какой был результат и почему перестал\"></textarea></div></div>\n      <div class=\"section\"><h3>Пищеварение и реакция организма</h3><p class=\"section-note\">Выбери симптомы, которые повторялись в течение последнего месяца. Затем напиши, как часто они возникают и с какими продуктами или ситуациями связаны.</p><div class=\"chips\" data-group=\"Пищеварение\"><label class=\"chip\"><input type=\"checkbox\" value=\"Изжога/рефлюкс\"><span>Изжога / кислый привкус</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Вздутие\"><span>Вздутие живота</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Тяжесть после еды\"><span>Тяжесть после еды</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Тошнота\"><span>Тошнота</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Боль/спазмы\"><span>Боль или спазмы в животе</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Запор\"><span>Запор</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Жидкий стул\"><span>Жидкий стул</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нерегулярный стул\"><span>Нерегулярный стул</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сонливость после еды\"><span>Сонливость после еды</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Тяга к сладкому\"><span>Сильная тяга к сладкому</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет симптомов\"><span>Ничего из перечисленного</span></label></div><div class=\"field\"><label class=\"label\">Опиши выбранные симптомы подробнее</label><textarea class=\"control\" name=\"Пищеварение подробно\" placeholder=\"Как часто, после какой еды, через сколько времени после приёма пищи и что помогает\"></textarea></div><div class=\"field\"><label class=\"label\">Замечаешь ли изменения кожи, волос или ногтей?</label><textarea class=\"control\" name=\"Кожа волосы ногти\" placeholder=\"Например: сухость кожи, высыпания, выпадение волос, ломкость или изменение ногтей — что именно и как давно\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Психология и изменения\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 7 из 12</div><h2>Ресурс для изменений</h2><p class=\"chapter-desc\">Здесь мне важно понять твоё текущее состояние, уровень стресса, поддержку и то, что может мешать выполнять план регулярно.</p></div>\n      <div class=\"section\"><h3>Последние две недели</h3><p class=\"section-note\">Оцени общее состояние своими словами и по шкалам.</p><div class=\"grid2\"><div class=\"field\"><span class=\"label\">Энергия</span><div class=\"scale\" data-scale=\"Психология: энергия 0-10\"></div></div><div class=\"field\"><span class=\"label\">Настроение</span><div class=\"scale\" data-scale=\"Психология: настроение 0-10\"></div></div><div class=\"field\"><span class=\"label\">Уровень стресса</span><div class=\"scale\" data-scale=\"Психология: стресс 0-10\"></div></div><div class=\"field\"><span class=\"label\">Ощущение контроля над жизнью</span><div class=\"scale\" data-scale=\"Психология: контроль 0-10\"></div></div></div><div class=\"field\"><label class=\"label\">Что сейчас создаёт больше всего напряжения?</label><textarea class=\"control\" name=\"Источники стресса\"></textarea></div><div class=\"field\"><label class=\"label\">Что помогает восстанавливаться эмоционально?</label><textarea class=\"control\" name=\"Психологические ресурсы\"></textarea></div><div class=\"field\"><label class=\"label\">Работаешь ли с психологом/психиатром? Есть ли важные состояния или назначения?</label><textarea class=\"control\" name=\"Психологическая помощь\"></textarea></div></div>\n      <div class=\"section\"><h3>Готовность и барьеры</h3><div class=\"grid2\"><div class=\"field\"><span class=\"label\">Насколько результат важен?</span><div class=\"scale\" data-scale=\"Важность изменений 0-10\"></div></div><div class=\"field\"><span class=\"label\">Насколько уверен, что справишься?</span><div class=\"scale\" data-scale=\"Уверенность в изменениях 0-10\"></div></div></div><div class=\"chips\" data-group=\"Барьеры\"><label class=\"chip\"><input type=\"checkbox\" value=\"Нет времени\"><span>Время</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Усталость\"><span>Усталость</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Боль/страх\"><span>Боль / страх</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет поддержки\"><span>Нет поддержки</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Срывы режима\"><span>Режим</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Командировки\"><span>Командировки</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Перфекционизм\"><span>Всё или ничего</span></label></div><div class=\"field\"><label class=\"label\">Что обычно мешало продолжать раньше?</label><textarea class=\"control\" name=\"Причины прошлых срывов\"></textarea></div><div class=\"field\"><label class=\"label\">Какая поддержка поможет не бросить?</label><textarea class=\"control\" name=\"Нужная поддержка\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Восстановление и природные практики\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 8 из 12</div><h2>Как ты восстанавливаешься</h2><p class=\"chapter-desc\">Мне важно понять, что ты уже используешь для отдыха и восстановления и какие практики хорошо воспринимает твоё тело.</p></div>\n      <div class=\"section\"><h3>Восстановление</h3><div class=\"chips\" data-group=\"Практики восстановления\"><label class=\"chip\"><input type=\"checkbox\" value=\"Прогулки\"><span>Прогулки</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Массаж\"><span>Массаж</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Сауна/баня\"><span>Сауна / баня</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Растяжка\"><span>Растяжка</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Дыхательные практики\"><span>Дыхание</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Медитация\"><span>Медитация</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Ничего регулярно\"><span>Ничего регулярно</span></label></div><div class=\"field\"><span class=\"label\">Насколько восстанавливаешься между нагрузками?</span><div class=\"scale\" data-scale=\"Восстановление между нагрузками 0-10\"></div></div><div class=\"field\"><label class=\"label\">Признаки перегруза и твоя реакция на них</label><textarea class=\"control\" name=\"Признаки перегруза\"></textarea></div></div>\n      <div class=\"section\"><h3>Холод, тепло и время на природе</h3><p class=\"section-note\">Выбери практики, которые ты используешь сейчас или регулярно использовал раньше. Мне это нужно, чтобы понять твой опыт, привычную нагрузку и реакцию на холод, тепло и пребывание на природе.</p><div class=\"chips\" data-group=\"Природные практики\"><label class=\"chip\"><input type=\"checkbox\" value=\"Контрастный душ\"><span>Контрастный душ</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Холодный душ\"><span>Холодный душ</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Купание в холодной воде\"><span>Купание в холодной воде</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Баня/сауна\"><span>Баня / сауна</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Утренний свет\"><span>Прогулка и свет утром</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Ходьба босиком\"><span>Хожу босиком</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Природа/лес\"><span>Регулярно бываю на природе</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет опыта\"><span>Ничего из перечисленного</span></label></div><div class=\"field\"><label class=\"label\">Расскажи подробнее о выбранных практиках</label><textarea class=\"control\" name=\"Опыт закаливания\" placeholder=\"Как часто, сколько времени, насколько холодно или жарко, как чувствуешь себя во время и после, зачем используешь эту практику\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Биометрика и специальные ветки\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 9 из 12</div><h2>Дополнительные данные</h2><p class=\"chapter-desc\">Если ты используешь часы, кольцо, браслет или приложение для здоровья, их данные помогут мне точнее увидеть твою обычную активность и восстановление.</p></div>\n      <div class=\"section\"><h3>Часы, кольца и приложения</h3><p class=\"section-note\">Отметь устройство, которым действительно пользуешься. Если ничего не отслеживаешь — выбери «не использую» и переходи дальше.</p><div class=\"chips\" data-group=\"Устройства\"><label class=\"chip\"><input type=\"checkbox\" value=\"Apple Watch\"><span>Apple Watch</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Garmin\"><span>Garmin</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Oura\"><span>Oura</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Whoop\"><span>Whoop</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Другое\"><span>Другое устройство / приложение</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Нет\"><span>Не использую</span></label></div><div class=\"field\"><label class=\"label\">Если данные есть, напиши средние значения за последние 2–4 недели</label><span class=\"hint\">Это будет очень полезно для оценки реальной нагрузки. Можно просто переписать цифры из приложения или приложить скриншоты вместе с фото и видео.</span><textarea class=\"control\" name=\"Биометрика\" placeholder=\"Средние шаги в день, пульс в покое, HRV, длительность сна, VO₂max, вес и другие показатели, которые устройство показывает регулярно\"></textarea></div><div class=\"field\"><label class=\"label\">Какие показатели ты сам отслеживаешь особенно внимательно и почему?</label><textarea class=\"control\" name=\"Отношение к метрикам\" placeholder=\"Например: слежу за сном, потому что после плохой ночи тяжело тренироваться\"></textarea></div></div>\n      <div class=\"section conditional\" data-show=\"sex:Женский\"><h3>Женское здоровье</h3><p class=\"section-note\">Ответы помогут учитывать изменения энергии, самочувствия и переносимости нагрузки в разные периоды цикла.</p><div class=\"field\"><label class=\"label\">Как проходит менструальный цикл?</label><textarea class=\"control\" name=\"Женское здоровье: цикл\" placeholder=\"Регулярность и длительность цикла; боли, отёки, изменение настроения, аппетита и энергии; насколько это мешает обычной жизни и тренировкам\"></textarea></div><div class=\"field\"><label class=\"label\">Есть ли важный контекст, который нужно учитывать в плане?</label><textarea class=\"control\" name=\"Женское здоровье: контекст\" placeholder=\"Беременность, восстановление после родов, менопауза, ощущения в области тазового дна, подтекание мочи при кашле или прыжках, диастаз или другое\"></textarea></div></div>\n      <div class=\"section conditional\" data-show=\"sex:Мужской\"><h3>Мужское здоровье</h3><p class=\"section-note\">Эти вопросы помогают увидеть общую динамику энергии, восстановления и самочувствия. Выбери то, что повторяется, затем опиши подробнее.</p><div class=\"chips\" data-group=\"Мужское здоровье: особенности\"><label class=\"chip\"><input type=\"checkbox\" value=\"Снижение энергии\"><span>Снижение энергии</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Снижение либидо\"><span>Снижение либидо</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Изменение эрекции\"><span>Изменение эрекции</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Частое ночное мочеиспускание\"><span>Часто встаю ночью в туалет</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Изменение мочеиспускания\"><span>Изменился напор или частота мочеиспускания</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Снижение силы/мышечной массы\"><span>Снижение силы или мышечной массы</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Ничего из перечисленного\"><span>Ничего из перечисленного</span></label></div><div class=\"field\"><label class=\"label\">Если что-то выбрал, расскажи подробнее</label><textarea class=\"control\" name=\"Мужское здоровье: подробно\" placeholder=\"Как давно началось, как часто происходит и как менялось со временем\"></textarea></div></div>\n      <div class=\"section\"><h3>Спортивная ветка</h3><div class=\"field\"><span class=\"label\">Готовишься к соревнованиям?</span><div class=\"chips\"><label class=\"chip\"><input type=\"radio\" name=\"Соревнования\" value=\"Нет\" checked data-branch=\"athlete:no\"><span>Нет</span></label><label class=\"chip\"><input type=\"radio\" name=\"Соревнования\" value=\"Да\" data-branch=\"athlete:yes\"><span>Да</span></label></div></div><div class=\"conditional\" data-show=\"athlete:yes\"><div class=\"field\"><label class=\"label\">Вид спорта, уровень, дата и главная задача старта</label><textarea class=\"control\" name=\"Спорт: соревнования\"></textarea></div><div class=\"field\"><label class=\"label\">Тренировочный объём, календарь и работа с тренером</label><textarea class=\"control\" name=\"Спорт: нагрузка\"></textarea></div><div class=\"field\"><label class=\"label\">Что сейчас лимитирует результат?</label><textarea class=\"control\" name=\"Спорт: лимитирующие факторы\"></textarea></div></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Реальная среда\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 10 из 12</div><h2>План должен жить в твоей жизни</h2><p class=\"chapter-desc\">Время, место, инвентарь и формат — реальные, а не идеальные.</p></div>\n      <div class=\"section\"><h3>Время и расписание</h3><p class=\"section-note\">Мне нужно увидеть не идеальное, а реальное расписание, чтобы программа не конфликтовала с работой, семьёй и восстановлением.</p><div class=\"grid2\"><div class=\"field\"><label class=\"label\">Сколько дней в неделю ты реально готов выделять на занятия по программе?</label><select class=\"control\" name=\"Дней на тренировки\"><option value=\"\">Выбери</option><option>1</option><option>2</option><option>3</option><option>4</option><option>5+</option></select></div><div class=\"field\"><label class=\"label\">Сколько времени обычно можешь выделить на одно занятие?</label><select class=\"control\" name=\"Минут на тренировку\"><option value=\"\">Выбери</option><option>10–15 минут</option><option>20–30 минут</option><option>40–60 минут</option><option>Больше 60 минут</option></select></div></div><div class=\"field\"><label class=\"label\">В какие конкретно дни и время тебе удобнее заниматься?</label><span class=\"hint\">Также укажи смены, командировки, поездки, недели с детьми или другие обстоятельства, из-за которых график регулярно меняется.</span><textarea class=\"control\" name=\"Расписание\" placeholder=\"Например: понедельник, среда и пятница после 19:00; раз в месяц неделя командировок без доступа к залу\"></textarea></div><div class=\"field\"><label class=\"label\">Сколько времени ты точно найдёшь даже в очень загруженный день?</label><span class=\"hint\">По этому ответу я смогу подготовить короткую версию занятия, чтобы не выпадать из процесса полностью.</span><select class=\"control\" name=\"Минимальная версия плана\"><option value=\"\">Выбери</option><option>5 минут</option><option>10 минут</option><option>15 минут</option><option>20 минут</option><option>В загруженный день заниматься не смогу</option></select></div></div>\n      <div class=\"section\"><h3>Место и инвентарь</h3><div class=\"chips\" data-group=\"Места тренировок\"><label class=\"chip\"><input type=\"checkbox\" value=\"Дома\"><span>Дома</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Зал\"><span>Зал</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Студия\"><span>Студия</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Улица\"><span>Улица</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Командировки\"><span>В поездках</span></label></div><div class=\"field\"><label class=\"label\">Доступный инвентарь</label><textarea class=\"control\" name=\"Инвентарь\" placeholder=\"Коврик, резинки, гантели, гири, турник, тренажёры и т. д.\"></textarea></div><div class=\"field\"><label class=\"label\">Что готов приобрести при необходимости?</label><input class=\"control\" name=\"Готов приобрести\"></div></div>\n      <div class=\"section\"><h3>Формат работы</h3><div class=\"chips\" data-group=\"Предпочтительный формат\"><label class=\"chip\"><input type=\"checkbox\" value=\"Самостоятельно\"><span>Самостоятельно</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео-программа\"><span>Видео-программа</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Онлайн-сессии\"><span>Онлайн</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Студия\"><span>В студии</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Личное ведение\"><span>Личное ведение</span></label></div><div class=\"field\"><label class=\"label\">Как тебе удобнее получать задания и обратную связь?</label><textarea class=\"control\" name=\"Коммуникация и обратная связь\"></textarea></div></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Фото и видео\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 11 из 12</div><h2>Увидеть тело в движении</h2><p class=\"chapter-desc\">Файлы не загружаются в эту страницу: отправь их отдельно по согласованному защищённому каналу.</p></div>\n      <div class=\"section\"><h3>Материалы до встречи</h3><p class=\"section-note\">Отметь материалы, которые уже снял или готов снять. Они позволяют заранее увидеть осанку, дыхание и то, как тело выполняет базовые движения.</p><div class=\"chips\" data-group=\"Готовность материалов\"><label class=\"chip\"><input type=\"checkbox\" value=\"Фото спереди\"><span>Фото спереди</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Фото сбоку\"><span>Фото сбоку</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Фото сзади\"><span>Фото сзади</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео ходьбы\"><span>Ходьба</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео приседа\"><span>Присед</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео наклона\"><span>Наклон</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео рук вверх\"><span>Руки вверх</span></label><label class=\"chip\"><input type=\"checkbox\" value=\"Видео дыхания\"><span>Дыхание</span></label></div><div class=\"notice\"><strong>Как снимать:</strong> поставь камеру неподвижно, чтобы тело было видно полностью; выбери однотонную удобную одежду и хорошее освещение. Каждое движение выполни спокойно, в обычной для тебя манере.</div><div class=\"field\"><label class=\"label\">Ссылка на папку с материалами (необязательно)</label><input class=\"control\" type=\"url\" name=\"Ссылка на фото и видео\" placeholder=\"https://...\"></div><div class=\"field\"><label class=\"label\">Есть ли конкретное движение или ситуация, которые особенно важно показать?</label><textarea class=\"control\" name=\"Комментарий к материалам\" placeholder=\"Например: при приседании заваливаюсь вправо; после пяти минут бега начинает тянуть голень; не могу поднять левую руку так же высоко, как правую\"></textarea></div></div>\n      <div class=\"section\"><h3>Согласие</h3><div class=\"field\"><label class=\"chip\"><input type=\"checkbox\" name=\"Согласие на обработку\" value=\"Да\" required><span>Согласен(на) на обработку ответов для подготовки персональной стратегии <b class=\"req\">*</b></span></label></div><div class=\"field\"><label class=\"chip\"><input type=\"checkbox\" name=\"Согласие на фото-видео\" value=\"Да\"><span>Согласен(на) на анализ отправленных отдельно фото и видео</span></label></div><p class=\"skip\">Публикация материалов не разрешается этим согласием и требует отдельного явного разрешения.</p></div>\n    </section>\n\n    <section class=\"chapter\" data-title=\"Паспорт клиента\">\n      <div class=\"chapter-head\"><div class=\"chapter-index\">Глава 12 из 12</div><h2>Твой паспорт готов</h2><p class=\"chapter-desc\">Проверь структурированную сводку. Ты контролируешь, куда она отправится.</p></div>\n      <div class=\"section\"><h3>Последнее важное</h3><div class=\"field\"><label class=\"label\">Что я не спросил, но должен знать?</label><textarea class=\"control\" name=\"Дополнительная информация\"></textarea></div><div class=\"field\"><label class=\"label\">Три главных факта обо мне для тренера</label><textarea class=\"control\" name=\"Три главных факта\"></textarea></div><button class=\"btn primary\" type=\"button\" id=\"buildSummary\">Обновить паспорт клиента</button></div>\n      <div class=\"section\"><h3>Структурированный результат</h3><p class=\"section-note\">Здесь собраны только заполненные ответы. Самая важная информация о здоровье и самочувствии будет показана в начале.</p><div class=\"summary\" id=\"summary\" aria-live=\"polite\">Нажми «Обновить паспорт клиента».</div><div class=\"actions\"><button class=\"btn primary\" type=\"button\" id=\"copyBtn\">Скопировать</button><button class=\"btn\" type=\"button\" id=\"downloadBtn\">Скачать .txt</button><button class=\"btn\" type=\"button\" id=\"shareBtn\">Поделиться</button><button class=\"btn\" type=\"button\" id=\"sendBtn\">Безопасно отправить</button></div><p class=\"skip\" id=\"actionState\">Секретные токены и ключи в HTML не используются.</p></div>\n    </section>\n\n    <div class=\"nav\"><button class=\"btn\" type=\"button\" id=\"prevBtn\">Назад</button><button class=\"btn primary\" type=\"button\" id=\"nextBtn\">Дальше</button></div>\n    <p class=\"footer-note\">Персональная стратегия тела · конфиденциальная анкета клиента</p>\n  </form></main>\n\n  <dialog id=\"sendDialog\"><h2>Отправка анкеты</h2><p>Отправка идёт на защищённый сервер сайта. Секреты Telegram хранятся только на сервере и не попадают в браузер.</p><button class=\"btn primary\" data-close-dialog=\"1\" type=\"button\">Понятно</button></dialog>\n\n  \n";
